using System.Globalization;
using System.Runtime.CompilerServices;
using System.Text.Json;

public record LogEntry(DateTime Time, string Level, string Source, string Message);

public record Report(
    int Entries, int Malformed,
    SortedDictionary<string, int> ByLevel,
    List<string> TopErrorSources,
    DateTime? First, DateTime? Last,
    int? BusiestHour,
    List<string> MissingFiles);

public static class LogTools
{
    private static readonly string[] Levels = { "DEBUG", "INFO", "WARN", "ERROR" };

    private static readonly JsonSerializerOptions Json = new()
    {
        PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
        WriteIndented = true,
    };

    private static bool IsSourceChar(char c) =>
        (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '.' || c == '-' || c == '_';

    // "<time> [<level>] <source>: <message>", cut apart at its separators.
    public static LogEntry? ParseLine(string line)
    {
        int space = line.IndexOf(' ');
        if (space < 0) return null;
        if (!DateTime.TryParseExact(line.Substring(0, space), "yyyy-MM-ddTHH:mm:ssZ", CultureInfo.InvariantCulture,
                DateTimeStyles.AdjustToUniversal | DateTimeStyles.AssumeUniversal, out var time))
            return null;
        string rest = line.Substring(space + 1);
        int close = rest.IndexOf("] ");
        if (!rest.StartsWith('[') || close < 0) return null;
        string level = rest.Substring(1, close - 1).ToUpperInvariant();
        if (!Levels.Contains(level)) return null;
        rest = rest.Substring(close + 2);
        int colon = rest.IndexOf(": ");
        if (colon <= 0) return null;
        string source = rest.Substring(0, colon);
        if (!source.All(IsSourceChar)) return null;
        return new LogEntry(time, level, source, rest.Substring(colon + 2));
    }

    public static async IAsyncEnumerable<LogEntry> ReadAsync(string path, [EnumeratorCancellation] CancellationToken ct = default)
    {
        using var reader = new StreamReader(path);
        string? line;
        while ((line = await reader.ReadLineAsync(ct)) != null)
        {
            if (ParseLine(line) is LogEntry entry) yield return entry;
        }
    }

    private static async Task<(List<LogEntry> Entries, int Malformed)> ReadFileAsync(string path, CancellationToken ct)
    {
        var entries = new List<LogEntry>();
        int malformed = 0;
        using var reader = new StreamReader(path);
        string? line;
        while ((line = await reader.ReadLineAsync(ct)) != null)
        {
            if (string.IsNullOrWhiteSpace(line)) continue;
            if (ParseLine(line) is LogEntry entry) entries.Add(entry);
            else malformed++;
        }
        return (entries, malformed);
    }

    public static async Task<Report> AnalyzeAsync(IEnumerable<string> paths, CancellationToken ct = default)
    {
        var all = paths.ToList();
        var missing = all.Where(p => !File.Exists(p)).Order(StringComparer.Ordinal).ToList();
        var results = await Task.WhenAll(all.Where(File.Exists).Select(p => ReadFileAsync(p, ct)));
        var entries = results.SelectMany(r => r.Entries).ToList();

        var byLevel = new SortedDictionary<string, int>(StringComparer.Ordinal);
        foreach (var e in entries) byLevel[e.Level] = byLevel.GetValueOrDefault(e.Level) + 1;

        var topErrors = entries.Where(e => e.Level == "ERROR")
            .GroupBy(e => e.Source)
            .OrderByDescending(g => g.Count()).ThenBy(g => g.Key, StringComparer.Ordinal)
            .Take(3).Select(g => g.Key).ToList();

        int? busiest = entries.Count == 0 ? null
            : entries.GroupBy(e => e.Time.Hour).OrderByDescending(g => g.Count()).ThenBy(g => g.Key).First().Key;

        return new Report(
            entries.Count, results.Sum(r => r.Malformed), byLevel, topErrors,
            entries.Count == 0 ? null : entries.Min(e => e.Time),
            entries.Count == 0 ? null : entries.Max(e => e.Time),
            busiest, missing);
    }

    public static async Task SaveAsync(Report report, string path)
    {
        await using var stream = File.Create(path);
        await JsonSerializer.SerializeAsync(stream, report, Json);
    }

    public static async Task<Report?> LoadAsync(string path)
    {
        try
        {
            await using var stream = File.OpenRead(path);
            return await JsonSerializer.DeserializeAsync<Report>(stream, Json);
        }
        catch (Exception e) when (e is FileNotFoundException or JsonException)
        {
            return null;
        }
    }
}

unitTests:
string dir = Path.Combine(Path.GetTempPath(), "xenon-logs-" + Guid.NewGuid().ToString("N"));
Directory.CreateDirectory(dir);
string P(string name) => Path.Combine(dir, name);
static T Run<T>(Task<T> t) => t.GetAwaiter().GetResult();

File.WriteAllLines(P("web.log"), new[]
{
    "2026-03-14T09:30:05Z [ERROR] auth: login failed for user 17",
    "2026-03-14T09:31:00Z [INFO] web: GET /home 200",
    "garbage line",
    "",
    "2026-03-14T10:02:00Z [error] auth: token expired",
    "2026-03-14T10:05:00Z [WARN] web: slow response",
});
File.WriteAllLines(P("db.log"), new[]
{
    "2026-03-14T08:59:59Z [ERROR] db.main: connection lost",
    "2026-03-14T10:10:00Z [ERROR] web: 500 on /pay",
    "2026-03-14T10:11:00Z [DEBUG] db.main: ",
    "2026-13-14T10:11:00Z [INFO] db: bad month",
    "2026-03-14T10:12:00Z [TRACE] db: unknown level",
});

Test("parsing lines", () =>
{
    var e = LogTools.ParseLine("2026-03-14T09:30:05Z [error] auth-svc_2: login failed: twice")!;
    CheckEq(e.Time, new DateTime(2026, 3, 14, 9, 30, 5, DateTimeKind.Utc));
    CheckEq(e.Time.Kind, DateTimeKind.Utc);
    CheckEq((e.Level, e.Source, e.Message), ("ERROR", "auth-svc_2", "login failed: twice"));
    CheckEq(LogTools.ParseLine("2026-03-14T09:30:05Z [INFO] web: ")!.Message, "");
    foreach (string bad in new[] { "", "hello", "2026-03-14 09:30:05Z [INFO] web: x", "2026-03-14T09:30:05Z [INFO] web x",
                                   "2026-03-14T09:30:05Z [NOTE] web: x", "2026-02-30T09:30:05Z [INFO] web: x" })
        CheckEq(LogTools.ParseLine(bad), null);
});

Test("reading one file lazily", () =>
{
    var list = new List<string>();
    Task.Run(async () => { await foreach (var e in LogTools.ReadAsync(P("web.log"))) list.Add(e.Source); }).GetAwaiter().GetResult();
    CheckEq(list, new[] { "auth", "web", "auth", "web" });
    using var cts = new CancellationTokenSource();
    cts.Cancel();
    CheckThrows<OperationCanceledException>(() =>
        Task.Run(async () => { await foreach (var e in LogTools.ReadAsync(P("web.log"), cts.Token)) { } }).GetAwaiter().GetResult());
});

Test("analyzing several files", () =>
{
    var r = Run(LogTools.AnalyzeAsync(new[] { P("web.log"), P("missing.log"), P("db.log") }));
    CheckEq(r.Entries, 7);
    CheckEq(r.Malformed, 3);
    CheckEq(r.ByLevel, new SortedDictionary<string, int> { ["DEBUG"] = 1, ["ERROR"] = 4, ["INFO"] = 1, ["WARN"] = 1 });
    CheckEq(r.TopErrorSources, new[] { "auth", "db.main", "web" });
    CheckEq(r.First, new DateTime(2026, 3, 14, 8, 59, 59, DateTimeKind.Utc));
    CheckEq(r.Last, new DateTime(2026, 3, 14, 10, 11, 0, DateTimeKind.Utc));
    CheckEq(r.BusiestHour, 10);
    CheckEq(r.MissingFiles, new[] { P("missing.log") });
});

Test("an empty analysis", () =>
{
    var r = Run(LogTools.AnalyzeAsync(new[] { P("nothing-here.log") }));
    CheckEq((r.Entries, r.Malformed, r.ByLevel.Count, r.TopErrorSources.Count), (0, 0, 0, 0));
    CheckEq(r.First, null);
    CheckEq(r.BusiestHour, null);
});

Test("saving and loading the report", () =>
{
    var r = Run(LogTools.AnalyzeAsync(new[] { P("web.log"), P("db.log") }));
    LogTools.SaveAsync(r, P("report.json")).GetAwaiter().GetResult();
    string json = File.ReadAllText(P("report.json"));
    Check(json.Contains("\"topErrorSources\""), "names should be camelCase");
    Check(json.Contains('\n'), "the JSON should be indented");
    var back = Run(LogTools.LoadAsync(P("report.json")))!;
    CheckEq(back.Entries, r.Entries);
    CheckEq(back.ByLevel["ERROR"], 4);
    CheckEq(back.Last, r.Last);
    CheckEq(Run(LogTools.LoadAsync(P("absent.json"))), null);
    File.WriteAllText(P("broken.json"), "{ nope");
    CheckEq(Run(LogTools.LoadAsync(P("broken.json"))), null);
});

